add(6,'Cơ học Newton cho chất điểm','A2 · Cơ học',
'Trước khi xét thân drone quay, hãy coi toàn bộ khối lượng tập trung ở một điểm để hiểu lực quyết định chuyển động tịnh tiến.',
['Dùng ba định luật Newton đúng hệ quy chiếu','Lập phương trình lực cho drone theo phương thẳng đứng','Mô tả ảnh hưởng của lực cản không khí'],[
('Ba định luật và hệ quán tính','<p>Định luật I: nếu tổng lực bằng 0, vật giữ vận tốc không đổi trong hệ quán tính. Định luật II: ΣF=d(mv)/dt=ma khi m không đổi. Định luật III: hai vật tương tác tác dụng lực bằng độ lớn, ngược hướng lên hai vật khác nhau. Cánh quạt đẩy không khí xuống; không khí đẩy cánh quạt lên.</p><p>World ENU gần như hệ quán tính cho chuyến bay ngắn. Hệ body quay cùng drone không quán tính, nên nếu viết toàn bộ động lực học trong body phải có các số hạng quán tính bổ sung.</p>'),
('Động lượng, xung lượng, năng lượng','<p>Động lượng p=mv; xung lượng ∫Fdt=Δp. Công W=∫F·dr, động năng K=½mv², thế năng trọng trường U=mgz. Nếu bỏ cản, công của motor làm tăng K+U. Khi hover lý tưởng, năng lượng cơ của drone không đổi nhưng motor vẫn tốn điện vì liên tục truyền động lượng cho không khí.</p>'),
('Các lực thường gặp','<p>Trọng lực Fg=(0,0,−mg). Lực cản tịnh tiến gần đúng Fd=−½ρCdA|v_rel|v_rel; với tốc độ rất nhỏ đôi khi dùng −cv_rel. Lực đàn hồi F=−kx xuất hiện ở chân đáp hoặc hệ treo thử nghiệm. Phương trình chất điểm:</p><div class="formula">m r̈ = (0,0,−mg) + R(0,0,T) + Fd + Fgió + …</div><p>Ở tư thế thẳng đứng, không có cản và z hướng lên: m z̈=T−mg. Với m=1 kg, T=11,81 N, gia tốc lên là 2 m/s².</p>')],
'forces','Tổng lực đẩy T hướng lên; trọng lực mg hướng xuống; cản ngược chiều vận tốc tương đối.',
'Mô phỏng rơi thẳng đứng với m=1 kg, CdA=0,05 m², ρ=1,225 kg/m³ bằng Euler hoặc RK4. So vận tốc khi có và không có cản; kiểm tra cản luôn ngược chiều v_rel.',
['Tại sao đang hover vẫn tiêu thụ công suất?','Nếu gió thổi cùng chiều chuyển động, lực cản tính theo v hay v_rel?'],'hover')

add(7,'Cơ học vật rắn','A2 · Cơ học',
'Lực đặt lệch khối tâm làm thân drone quay. Phân bố khối lượng quyết định drone quay nhanh hay chậm với cùng mô-men.',
['Tính mô-men lực quanh khối tâm','Giải thích tensor quán tính và trục chính','Đọc được phương trình Euler cho vật rắn'],[
('Khối tâm và mô-men','<p>Khối tâm rCG=Σmᵢrᵢ/Σmᵢ. Ta chọn gốc body tại đó để trọng lực không tạo mô-men quanh gốc. Pin lắp lệch làm CG dịch đi; các cánh tay đòn từ CG đến motor thay đổi, nên hover cân bằng có thể cần thrust khác nhau. Mô-men của lực F đặt tại r là τ=r×F; mô-men tổng là tổng các tích có hướng.</p>'),
('Moment quán tính là một tensor','<p>Quán tính quay quanh một trục là tổng mᵢdᵢ²; vật nặng đặt xa trục khó quay hơn. Trong 3D cần ma trận J đối xứng 3×3. Đường chéo Jxx,Jyy,Jzz là moment quanh các trục; phần tử ngoài đường chéo đo ghép giữa trục. Với drone đối xứng gần trục body, các phần tử ghép thường nhỏ, nhưng pin/camera lệch làm chúng đáng kể.</p><div class="formula">J = Σ mᵢ (||rᵢ||² I − rᵢrᵢᵀ), &nbsp; L = Jω</div><p>Vector riêng của J cho các trục chính; trị riêng tương ứng là moment quán tính quanh chúng.</p>'),
('Phương trình Euler','<p>Đạo hàm mô-men động lượng trong hệ quay cần định lý vận chuyển. Vì vậy:</p><div class="formula">Jω̇ + ω × (Jω) = τ</div><p>Số hạng ω×Jω ghép các trục: ngay cả khi τx=0, ωx vẫn có thể đổi nếu drone vừa pitch vừa yaw và Jyy≠Jzz. Trường hợp J≈diag(Jxx,Jyy,Jzz), phương trình roll là Jxx ṗ + (Jzz−Jyy)qr=τx.</p>')],
'inertia','Cùng lực, khối lượng nằm xa trục tạo moment quán tính lớn hơn và gia tốc góc nhỏ hơn.',
'Ước lượng J bằng CAD với đúng vị trí pin, camera, motor. Nếu không có CAD, dùng con lắc hai dây: đo chu kỳ P, khối lượng m, chiều dài dây L và nửa khoảng cách hai dây a; với góc nhỏ J≈mga²P²/(4π²L). Ghi sai số đo P và a.',
['Nếu đưa pin ra xa trục yaw thì Jzz thay đổi thế nào?','ω×Jω có thể khác 0 khi J là bội của I không?'],'moment')

add(8,'Khí động học cơ bản','A3 · Khí động học và động cơ',
'Cánh quạt trao đổi động lượng với không khí. Mật độ và tốc độ dòng khí vì thế ảnh hưởng trực tiếp đến lực đẩy.',
['Giải thích vì sao đẩy khí xuống tạo lực lên','Phân biệt lift, drag và góc tấn','Ước lượng lực cản thân drone'],[
('Không khí là môi trường làm việc','<p>Mật độ ρ khoảng 1,225 kg/m³ ở mực nước biển trong khí quyển chuẩn, nhưng đổi theo nhiệt độ, áp suất và độ cao. Độ nhớt ảnh hưởng lớp biên và Reynolds. Liên tục khối lượng cho dòng ổn định: ṁ=ρAv, cùng lượng khí đi qua một tiết diện mỗi giây. Bảo toàn động lượng nói lực ròng bằng tốc độ đổi động lượng của dòng khí.</p>'),
('Bernoulli và lực trên cánh','<p>Trong dòng không nhớt, ổn định, dọc cùng một đường dòng, p+½ρv²+ρgz gần như hằng số. Cánh có góc tấn α so với dòng khí; chênh áp và chuyển hướng dòng khí tạo lift vuông góc dòng tới, drag song song ngược dòng tới. Hệ số CL, CD gói hình dạng, α, Reynolds và các hiệu ứng khác:</p><div class="formula">L=½ρV²S CL, &nbsp; D=½ρV²S CD</div><p>Không thể suy ra lift chỉ bằng câu “khí đi trên nhanh hơn” mà bỏ điều kiện dòng chảy. Cách nhìn chắc chắn hơn là cánh làm lệch động lượng không khí xuống và nhận phản lực lên.</p>'),
('Cản thân drone','<p>Với vận tốc tương đối v_rel so với không khí, ước lượng độ lớn Fdrag≈½ρCdA v_rel². CdA là tích hệ số cản và diện tích cản trực diện, có thể thay đổi khi drone nghiêng. Ví dụ CdA=0,06 m², v=10 m/s cho Fdrag≈3,68 N tại ρ=1,225 kg/m³; ở 2 m/s chỉ khoảng 0,147 N.</p><div class="concept warning">Bernoulli chỉ là một công cụ trong các giả thiết phù hợp. Rotor thực có dòng xoáy, độ nhớt, nhiễu loạn và tốc độ thay đổi theo bán kính.</div>')],
'air','Rotor tăng tốc khối không khí xuống; phản lực tác dụng lên drone hướng lên.',
'Chọn CdA từ một ước lượng hình học, tính cản tại 2, 5, 10 m/s và vẽ Fdrag theo v². Thử thay ρ để thấy bay cao làm thay đổi kết quả.',
['Nếu tốc độ gấp đôi thì mô hình cản bậc hai tăng mấy lần?','Áp dụng Bernoulli cho toàn bộ dòng xoáy rotor có hợp lý không?'])

add(9,'Lý thuyết cánh quạt: từ không khí đến lực nâng','A3 · Khí động học và động cơ',
'Từ một đĩa gia tốc không khí, ta suy ra công suất hover và quy luật thrust gần tỉ lệ bình phương tốc độ quay.',
['Dẫn xuất vận tốc cảm ứng và công suất hover','Hiểu vì sao cánh lớn tiết kiệm công suất cảm ứng','Dùng CT, CQ để tính thrust và mô-men'],[
('Actuator disk khi hover','<p>Coi rotor như một đĩa diện tích A=π(D/2)². Ở xa phía trên, không khí đứng yên; tại đĩa nó đi xuống với vận tốc cảm ứng vᵢ; xa phía dưới trong mô hình lý tưởng nó đạt 2vᵢ. Lưu lượng qua đĩa ṁ=ρAvᵢ. Biến thiên động lượng cho T=ṁ(2vᵢ)=2ρAvᵢ². Vì vậy:</p><div class="formula">v_h = √(T/(2ρA)), &nbsp; P_ideal = T v_h = T³ᐟ² / √(2ρA)</div><p>Viết T=ṁv_out chỉ đúng khi v_in≈0 và v_out là độ tăng vận tốc xa dưới dòng khí; tại đĩa vận tốc là một nửa v_out trong mô hình lý tưởng. Với cùng T, A lớn làm v_h và công suất cảm ứng giảm.</p>'),
('Rotor thật và figure of merit','<p>Công suất thật còn tổn hao do drag của profile cánh, đầu cánh, dòng xoáy và motor. Figure of merit FM=P_ideal/P_shaft tại hover, nhỏ hơn 1. Ví dụ T=2,5 N, D=0,254 m, ρ=1,225 cho v_h≈4,49 m/s và P_ideal≈11,2 W mỗi rotor. Nếu FM=0,65 thì công suất trên trục khoảng 17,2 W, chưa tính tổn hao điện.</p>'),
('Blade element và hệ số thực nghiệm','<p>Chia cánh thành các dải bán kính dr. Mỗi dải có tốc độ tiếp tuyến xấp xỉ Ωr, góc tấn thay đổi theo pitch cánh và vận tốc dòng; tính dL, dD rồi chiếu lên hướng trục và tiếp tuyến để tích phân T và Q. Dạng không thứ nguyên tiện dùng là:</p><div class="formula">T=Cₜρn²D⁴, &nbsp; Q=Cqρn²D⁵, &nbsp; n=Ω/(2π)</div><p>Nếu hình học, môi trường và hệ số gần như không đổi, T=kTΩ², Q=kQΩ² với kT=CₜρD⁴/(4π²), kQ=CqρD⁵/(4π²). Bay tiến đổi advance ratio nên CT,CQ thay đổi; ρ giảm theo độ cao làm thrust giảm tại cùng RPM. Không dùng một kT cố định cho mọi chế độ.</p>')],
'disk','Actuator disk: dòng khí tăng tốc từ 0 ở xa phía trên tới 2vᵢ ở xa phía dưới.',
'Với prop đường kính 10 inch, n=100 vòng/s, CT=0,10, CQ=0,01, ρ=1,225: tính T, Q, P=2πnQ. Sau đó so với bảng thrust của đúng cánh/motor hoặc thrust stand; hiệu chỉnh CT,CQ theo dữ liệu đo.',
['Vì sao tăng diện tích đĩa giảm công suất hover lý tưởng?','Nếu RPM tăng 20% và CT gần cố định, thrust tăng bao nhiêu?'],'prop')

add(10,'Motor tạo lực nâng và mô-men xoay','A3 · Khí động học và động cơ',
'Bốn thrust riêng lẻ được cộng và lấy mô-men quanh khối tâm để tạo bốn lệnh điều khiển T, roll, pitch, yaw.',
['Xác định dấu mô-men từ r×F','Tự viết mixer cho cấu hình X','Biết khi nào nghiệm mixer vượt giới hạn motor'],[
('Một quy ước motor nhất quán','<p>Nhìn từ trên, mũi hướng +x body, trái là +y, z hướng lên. Motor 1 trước trái (+a,+a), 2 trước phải (+a,−a), 3 sau phải (−a,−a), 4 sau trái (−a,+a), với a=L/√2 nếu L là khoảng cách từ tâm tới rotor. Rotor 1,3 quay CCW; 2,4 quay CW khi nhìn từ trên. Rotor quay CCW tạo mô-men phản lực lên thân theo yaw âm. Đổi sơ đồ đánh số hoặc chiều quay phải đổi các cột của mixer.</p>'),
('Từng trục điều khiển','<p>Tăng đều bốn Tᵢ làm T tổng tăng. Vì τ=r×(0,0,Tᵢ), thành phần roll là yᵢTᵢ và pitch là −xᵢTᵢ. Tăng cặp bên trái 1+4 tạo roll dương; tăng cặp phía sau 3+4 tạo pitch dương. Tăng nhóm CW 2+4 tương đối nhóm CCW 1+3 tạo yaw dương theo quy ước trên.</p><div class="formula">Tᵢ=kTΩᵢ², &nbsp; Qᵢ=kQΩᵢ², &nbsp; γ=kQ/kT [m]</div>'),
('Ma trận mixer cấu hình X','<p>Đặt s=[Ω₁²,Ω₂²,Ω₃²,Ω₄²]ᵀ. Khi đó [T,τx,τy,τz]ᵀ=Ms:</p><div class="formula">M = [[kT,kT,kT,kT], [akT,−akT,−akT,akT], [−akT,−akT,akT,akT], [−kQ,kQ,−kQ,kQ]]</div><p>Đặt γ=kQ/kT và Fᵢ=kTΩᵢ². Nghịch đảo có thể viết trực tiếp:</p><div class="formula">F₁=T/4+τx/(4a)−τy/(4a)−τz/(4γ); F₂=T/4−τx/(4a)−τy/(4a)+τz/(4γ)<br>F₃=T/4−τx/(4a)+τy/(4a)−τz/(4γ); F₄=T/4+τx/(4a)+τy/(4a)+τz/(4γ)</div><p>Từ đó Ωᵢ=√(Fᵢ/kT). Nếu Fᵢ âm hoặc vượt kTΩmax², yêu cầu không khả thi; cần bão hòa và phân bổ lại ưu tiên. Với cấu hình +, thay tọa độ rotor bằng (+L,0),(0,−L),(−L,0),(0,+L), rồi lập lại từng cột từ r×F.</p>')],
'mixer','Sơ đồ X: vị trí motor và chiều quay quyết định dấu mỗi cột trong ma trận mixer.',
'Tự viết M cho cấu hình X và +. Dùng numpy.linalg.matrix_rank(M) và M @ np.linalg.solve(M,u) để kiểm chứng. Thử u hover, roll thuần và yaw thuần; kiểm tra tổng thrust giữ nguyên ở hai ca sau.',
['Vì sao phải lấy căn bậc hai sau khi giải mixer?','Điều gì xảy ra khi một motor đã ở Ωmax nhưng yêu cầu T tiếp tục tăng?'],'mixer')

add(11,'Tổng hợp mọi lực và mô-men tác động','A3 · Khí động học và động cơ',
'Mô hình tốt là mô hình giữ các hiệu ứng đủ lớn cho câu hỏi đang nghiên cứu. Bài này giúp chọn mức chi tiết bằng ước lượng độ lớn.',
['Phân loại lực chính, hiệu ứng bậc hai và nhiễu','Ước lượng khi nào có thể bỏ qua từng hiệu ứng','Nhận diện ground effect và vortex ring state'],[
('Các tác động theo mức độ ưu tiên','<div class="table-wrap"><table><tr><th>Nhóm</th><th>Hiệu ứng và công thức gần đúng</th><th>Khi cần giữ</th></tr><tr><td>Lực chính</td><td>Trọng lực mg; tổng thrust T=ΣTᵢ</td><td>Luôn giữ</td></tr><tr><td>Mô-men chính</td><td>Roll/pitch Σrᵢ×Fᵢ; yaw Σ±Qᵢ</td><td>Luôn giữ; yaw thường yếu hơn roll/pitch</td></tr><tr><td>Bậc hai</td><td>Gyro rotor ≈Jr(ω×ωr); mô-men tăng tốc rotor JrΩ̇</td><td>Quay nhanh, đổi RPM nhanh, rotor có quán tính lớn</td></tr><tr><td>Bậc hai</td><td>Cản thân ½ρCdA|v_rel|v_rel; rotor drag, blade flapping</td><td>Bay tiến nhanh, mô phỏng quỹ đạo chính xác</td></tr><tr><td>Môi trường</td><td>Gió, nhiễu loạn, gust, ground effect, vortex ring, propwash</td><td>Bay thấp, hạ nhanh, đổi hướng gấp hoặc trời gió</td></tr><tr><td>Hệ thống</td><td>CG lệch, motor khác nhau, rung</td><td>Hiệu chỉnh và mô phỏng phần cứng cụ thể</td></tr></table></div>'),
('Hiểu đúng các hiệu ứng khó','<p>Rotor đang quay có mô-men động lượng JrΩ theo trục rotor. Khi thân quay, hướng vector này đổi và xuất hiện mô-men gyroscopic; hai cặp quay ngược chiều có thể triệt tiêu một phần, nhưng không hoàn toàn nếu RPM khác nhau. Khi rotor tăng tốc, thân nhận mô-men phản lực do JrΩ̇, đặc biệt ảnh hưởng yaw ngắn hạn.</p><p>Ground effect làm thay đổi dòng xuống khi rotor gần đất, thường tăng thrust với cùng công suất trong một vùng độ cao phụ thuộc đường kính cánh. Vortex ring state có thể xuất hiện khi hạ thẳng đứng nhanh trong chính dòng khí xoáy của rotor; không suy ra ngưỡng an toàn từ mô hình T=kTΩ². Propwash là dòng nhiễu từ rotor, ảnh hưởng cảm biến và cấu trúc khi cơ động.</p>'),
('Ước lượng bậc lớn','<p>Drone 1 kg có mg≈9,81 N. Nếu CdA=0,05 m², v_rel=10 m/s, ρ=1,225 thì drag≈3,06 N, đã bằng 31% trọng lực. Ở 2 m/s chỉ ≈0,123 N. Nếu a=0,18 m và chênh thrust 1 N giữa hai bên, mô-men roll bậc 0,18 N·m. So các số đo cùng đơn vị trước khi quyết định bỏ một hiệu ứng.</p><div class="concept warning">Các độ lớn trên là ví dụ minh họa, không phải thông số cho mọi drone. Rotor drag, ground effect và gyro cần dữ liệu riêng của cấu hình.</div>')],
'effects','Tầng mô hình: lực chính ở lõi; lực cản, rotor và môi trường bổ sung khi cần.',
'Chọn một drone cụ thể. Lập bảng m, L, CdA, Jr, tốc độ bay và gió dự kiến. Tính mg, drag tại hai tốc độ, mô-men từ chênh thrust 1 N; đánh dấu mục nào vượt 5% tác động chính.',
['Ở bay nhanh, có thể tiếp tục bỏ lực cản thân không?','Vì sao hai rotor CW và hai rotor CCW chỉ triệt tiêu gyro một phần?'])

add(12,'Động cơ BLDC, ESC và nguồn pin','A3 · Khí động học và động cơ',
'Lệnh điều khiển đi qua ESC, cuộn dây, rotor và pin trước khi trở thành thrust. Độ trễ và sụt áp giới hạn điều khiển.',
['Liên hệ Kv, Ke, Kt và tốc độ quay','Mô hình hóa trễ motor bậc nhất','Giải thích sụt áp pin và giới hạn thrust'],[
('Điện từ đến mô-men','<p>Dòng điện trong từ trường chịu lực Lorentz; các cuộn stator của BLDC tạo từ trường quay kéo rotor nam châm. Mô hình DC tương đương ở mức trung bình dùng V=Ri+KeΩ (+Ldi/dt nếu xét cảm kháng), mô-men τm=Kti. Trong hệ SI nhất quán, Ke [V·s/rad] và Kt [N·m/A] có cùng giá trị số với motor lý tưởng. Kv [RPM/V] thường được công bố; Kt≈60/(2πKv) nếu Kv là hằng số không tải theo RPM/V và bỏ tổn hao.</p>'),
('Cơ học rotor và ESC','<p>Rotor đáp ứng theo JrΩ̇=Kti−Qdrag(Ω). ESC điều khiển chuyển mạch pha và điện áp hiệu dụng; tín hiệu PWM/OneShot/DShot là cách flight controller gửi lệnh tới ESC, không phải trực tiếp tạo thrust. DShot là giao thức số; “PWM” ở đầu vào ESC và PWM đóng cắt công suất bên trong là hai lớp khác nhau.</p><div class="formula">Ω̇ = (Ωcmd−Ω)/τm</div><p>Mô hình bậc nhất này là xấp xỉ quanh một điểm làm việc. Sau bước lệnh, đáp ứng đạt khoảng 63% thay đổi cuối tại t=τm nếu không bão hòa.</p>'),
('Pin và chọn cấu hình','<p>Pin LiPo có điện áp hở mạch đổi theo trạng thái xả; dưới tải, Vterminal≈Voc−I Rinternal. Dòng lớn làm điện áp sụt, ESC không còn đủ điện áp để giữ RPM và thrust tối đa giảm. Chọn Kv, điện áp pin và đường kính/pitch prop theo tải: cánh lớn có thể hiệu quả hơn khi hover nhưng đòi mô-men cao hơn, tăng dòng và nhiệt. Đừng đánh giá chỉ bằng thrust tĩnh cực đại; cần xem hiệu suất và dư địa điều khiển.</p>')],
'motor','Chuỗi điện áp pin → ESC → dòng điện → mô-men motor → RPM → thrust.',
'Trên thrust stand có che chắn, đo bước lệnh ESC, RPM theo thời gian, thrust và dòng. Fit Ω(t)=Ω∞+(Ω0−Ω∞)e^(−t/τm); fit T=kTΩ², Q=kQΩ² nếu có cảm biến mô-men. Đo ở nhiều mức pin để thấy sự thay đổi.',
['Kv cao luôn cho thrust tốt hơn không?','Tại sao pin yếu làm mô hình mixer lý tưởng mất chính xác?'])

add(13,'Phương trình chuyển động đầy đủ','A4 · Tổng hợp thành mô hình',
'Ghép hình học, lực cánh quạt và cơ học vật rắn thành hàm đạo hàm trạng thái f(x,u) dùng trong simulator.',
['Viết hệ Newton–Euler đúng dấu ENU/FLU','Tìm điều kiện hover và tốc độ motor','Phân biệt trạng thái 12 và 13 biến'],[
('Chọn trạng thái và đầu vào','<p>Dùng rʷ∈R³, vʷ∈R³, quaternion q∈R⁴ và ωᵇ∈R³: tổng 13 số với ràng buộc |q|=1. Nếu thay q bằng Euler φ,θ,ψ, có 12 số nhưng kỳ dị tại pitch ±90°. Đầu vào vật lý là bốn tốc độ rotor Ωᵢ hoặc lệnh ESC; đầu vào trung gian tiện phân tích là u=[T,τx,τy,τz].</p>'),
('Hệ phương trình','<p>Với R(q) đổi body→world, e₃=(0,0,1)ᵀ, z world hướng lên và T dương theo +z body:</p><div class="formula">ṙ = v; &nbsp; m v̇ = −mg e₃ + T R e₃ + Fdrag + Fwind</div><div class="formula">q̇ = ½q⊗(0,ω); &nbsp; Jω̇ = τ − ω×(Jω) − τgyro</div><p>Nếu dùng DCM thay quaternion: Ṙ=R[ω]×. Dấu “−τgyro” chỉ đúng khi τgyro được định nghĩa là mô-men rotor tác dụng chống lại thân theo quy ước đã chọn; nếu định nghĩa là mô-men <em>lên thân</em>, phải cộng. Trong simulator nhập môn có thể đặt τgyro=0, Fdrag=0 để kiểm tra mô hình lõi.</p>'),
('Từ motor đến gia tốc và hover','<p>Tᵢ=kTΩᵢ² và Qᵢ=kQΩᵢ² đi qua ma trận mixer A10 để ra T,τ. Với R=I, v=0, ω=0 và bốn motor bằng nhau, hover yêu cầu T=mg:</p><div class="formula">Ωhover = √(mg/(4kT))</div><p>Ví dụ m=1 kg và kT=1,5×10⁻⁵ N/(rad/s)² thì Ωhover≈404,35 rad/s ≈3861 RPM. Đơn vị kT thay đổi nếu dùng RPM thay rad/s; không trộn hai hệ. Chuỗi nhân quả hoàn chỉnh: lệnh ESC → Ω → T,Q → gia tốc → vận tốc → vị trí.</p>')],
'flow','Các khối từ motor đến trạng thái nối tiếp nhau; quaternion quyết định hướng thrust trong world.',
'Viết hàm f(x,Ω) trả về 13 đạo hàm. Kiểm tra f ở hover: ṙ=0, v̇≈0, q̇=0, ω̇≈0. Sau đó tăng đều 5% Ω; kiểm tra T tăng khoảng 10,25% và gia tốc z dương.',
['Vì sao dùng quaternion cần 13 số nhưng tư thế vẫn có 3 bậc tự do?','Khi đổi sang NED/FRD, dấu nào trong phương trình tịnh tiến cần đổi?'],'tilt')

add(14,'Tuyến tính hóa và phân tích mô hình','A4 · Tổng hợp thành mô hình',
'Quanh hover, phương trình phi tuyến có thể được xấp xỉ bằng ma trận A, B để phân tích và thiết kế điều khiển.',
['Lập sai lệch quanh điểm cân bằng','Hiểu cực hệ hở và góc nhỏ','Kiểm tra điều khiển được và quan sát được'],[
('Điểm cân bằng và Jacobian','<p>Tại hover: r tùy ý, v=0, R=I (yaw bất kỳ nếu world ngang đồng đều), ω=0, T₀=mg, τ₀=0. Đặt δx=x−x₀ và δu=u−u₀, khai triển Taylor bậc nhất:</p><div class="formula">δẋ = Aδx + Bδu, &nbsp; A=(∂f/∂x)₀, &nbsp; B=(∂f/∂u)₀</div><p>Với Euler gần 0 và trạng thái [r,v,φ,θ,ψ,p,q,r] có 12 biến, góc nhỏ cho aₓ≈gθ, aᵧ≈−gφ, a_z≈δT/m. Dấu này xuất phát trực tiếp từ RzRyRx và FLU; nếu body y chọn sang phải, dấu aᵧ đổi.</p>'),
('Cực và ghép hệ con','<p>Hệ mở có các chuỗi tích phân: mô-men → gia tốc góc → góc, góc → gia tốc ngang → vận tốc → vị trí. Vì vậy nhiều trị riêng ở 0; drone không tự quay về vị trí/tư thế ban đầu sau nhiễu. Không nên gọi mọi cực ở 0 là “mất ổn định nổ”, nhưng hệ không ổn định tiệm cận và sai lệch có thể tích lũy.</p><p>Hệ con cao độ: δż=δvz, δv̇z=δT/m. Hệ con roll/y: δφ̇=p, ṗ=τx/Jxx, δv̇y=−gφ, δẏ=vy. Pitch/x tương tự với dấu gθ.</p>'),
('Điều khiển được và quan sát được','<p>Ma trận điều khiển được C=[B,AB,…,Aⁿ⁻¹B]; hạng n nghĩa là có thể điều khiển các trạng thái tuyến tính trong mô hình. Ma trận quan sát được O=[Cobs;CobsA;…;CobsAⁿ⁻¹] kiểm tra trạng thái có thể suy từ đầu ra cảm biến y=Cobs x hay không. Kết quả phụ thuộc chọn đầu ra: chỉ IMU không cho vị trí tuyệt đối nếu thiếu tham chiếu ngoài.</p><div class="concept warning">Tính hạng số cần ngưỡng hợp lý vì đơn vị giữa vị trí, góc và mô-men khác nhau. Khả điều khiển toán học chưa đảm bảo motor không bão hòa.</div>')],
'linear','Đường cong phi tuyến gần hover được thay bằng tiếp tuyến; xa điểm làm việc sai số tăng.',
'Dùng SymPy hoặc sai phân trung tâm để lấy A,B của f(x,u) tại hover; so hai phương pháp. Tính eig(A), rank(C), rồi chọn Cobs chỉ đo gyro và so với trường hợp có vị trí.',
['Vì sao lệnh mô-men không đổi làm góc tăng ngày càng nhanh trong mô hình mở?','Tuyến tính hóa quanh hover có đáng tin cho lật 90° không?'])

add(15,'Mô phỏng 6-DOF','A4 · Tổng hợp thành mô hình',
'Bài cuối ghép toàn bộ Phần A thành simulator có thể kiểm chứng bằng thí nghiệm đơn giản trước khi thiết kế bộ điều khiển.',
['Xây pipeline motor → động lực học → RK4','Thêm giới hạn, trễ, nhiễu và gió có kiểm soát','Dùng các ca kiểm chứng để phát hiện lỗi dấu và đơn vị'],[
('Kiến trúc simulator','<ol class="steps"><li>Lưu trạng thái x=(r,v,q,ω,Ω₁…Ω₄) nếu motor có động học; tổng 17 số, q được chuẩn hóa.</li><li>Nhận lệnh [Tcmd,τcmd] hoặc bốn lệnh motor; mixer ngược phân bổ tốc độ mục tiêu và kẹp vào [Ωmin,Ωmax].</li><li>Tính Ω̇ᵢ=(Ωcmdᵢ−Ωᵢ)/τm; dùng Ω hiện tại để tính Tᵢ,Qᵢ, rồi lực/mô-men.</li><li>Dùng phương trình A13 để tính ṙ,v̇,q̇,ω̇; tích phân RK4 từng bước và chuẩn hóa q.</li><li>Ghi log, vẽ vị trí, vận tốc, Euler để quan sát, Ω và điều khiển; hiển thị trục thân và quỹ đạo 3D.</li></ol>'),
('Các lớp thực tế','<p>Thêm bão hòa và tốc độ đổi lệnh motor, trễ ESC, gió trong world, drag theo v−vwind. Cảm biến giả tạo bằng cách lấy trạng thái thật cộng bias và nhiễu: gyro=ω+bias+noise; accelerometer đo specific force chứ không trực tiếp đo “trọng lực”. Dùng seed ngẫu nhiên cố định để so hai phiên bản simulator.</p><p>Điều quan trọng là tách “trạng thái thật” khỏi “đo cảm biến”. Mô hình sai số cảm biến sẽ phục vụ phần ước lượng trạng thái ở các phần sau.</p>'),
('Bộ kiểm chứng tối thiểu','<div class="table-wrap"><table><tr><th>Ca</th><th>Dự đoán lý thuyết</th><th>Dấu hiệu lỗi</th></tr><tr><td>Hover</td><td>z gần hằng, q=identity, Ωᵢ bằng nhau</td><td>Trôi z: sai mg/kT/đơn vị</td></tr><tr><td>Tăng đều Ω</td><td>z̈&gt;0, roll/pitch/yaw≈0</td><td>Nghiêng: mixer sai thứ tự</td></tr><tr><td>Roll thuần</td><td>ṗ cùng dấu τx; tâm gần chưa đổi lúc đầu</td><td>Roll ngược: dấu y hoặc cross product sai</td></tr><tr><td>Yaw thuần</td><td>ṙ góc yaw đúng dấu, T gần giữ nguyên</td><td>Bay vọt: phân bổ yaw đổi tổng thrust</td></tr><tr><td>Đổi bước h</td><td>RK4 hội tụ khi giảm h</td><td>Không hội tụ: lỗi động lực học hoặc chuẩn hóa</td></tr></table></div><p>So kết quả số với dự đoán ngắn hạn a=F/m và α≈τ/J. Chỉ thêm một hiệu ứng mới sau khi mô hình cơ bản qua kiểm chứng.</p>')],
'sim','Vòng mô phỏng: lệnh, motor, lực, Newton–Euler, tích phân, quan sát trạng thái.',
'Viết mô phỏng 10 s với Δt=0,002–0,01 s. Chạy năm ca trong bảng. Vẽ z(t), góc(t), Ωᵢ(t) và quỹ đạo 3D. Giảm Δt một nửa để so sai số; lưu cấu hình m,J,kT,kQ,L và seed gió.',
['Nếu tăng đều tốc độ motor 5%, thrust đổi bao nhiêu phần trăm?','Vì sao phải so kết quả với dự đoán vật lý trước khi thêm gió và nhiễu?'])
